<?php
use App\Core\{Auth,Authorization as A,Csrf,Database as DB,Validator as V};
use App\Services\{CourseAssignmentService as C,ContentImageService as Images,AssignmentAccessService as Access};
Auth::requireLogin();if(!A::isAdmin()&&!A::isTeacher())forbidden();$super=A::isSuperAdmin();$error=null;$form=[];
if(is_post()){
    Csrf::verifyRequest();if(!$super)forbidden();
    try{
        if(request_action()==='save_course'){$id=Images::save('courses',V::optInt($_POST['id']??null,'Course'),$_POST,$_FILES['cover_image']??null);flash('success','Course saved.');redirect('courses.php?id='.$id);}
        if(request_action()==='link_subject'){if(($_POST['active']??'')==='0'&&($_POST['confirm_removal']??'')!=='1')throw new DomainException('Confirm assignment deactivation first.');C::setCourseSubject(V::int($_POST['course_id']??'','Course',1),V::int($_POST['subject_id']??'','Subject',1),V::inList($_POST['active']??'',['0','1'],'Active')==='1');flash('success','Subject link updated.');redirect('courses.php?id='.(int)$_POST['course_id']);}
        throw new DomainException('Unknown action.');
    }catch(Throwable $e){$error=$e instanceof PDOException&&($e->errorInfo[1]??0)===1062?'This course code already exists.':handle_exception($e);$form=$_POST;}
}
$params=[];$where='1=1';
if(A::isCentreAdmin()){$scope=A::centreWhere('cc.centre_id',$params);$where="c.is_active=1 AND EXISTS(SELECT 1 FROM centre_courses cc WHERE cc.course_id=c.id AND cc.is_active=1 AND $scope)";}
elseif(A::isTeacher()){$ids=array_values(array_unique(array_column(Access::teacherAssignments((int)Auth::user()['id']),'course_id')));$where=$ids?'c.id IN ('.DB::in($ids).')':'1=0';$params=$ids;}
$q=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';if($q!==''){$where.=' AND (c.name LIKE ? OR c.code LIKE ?)';$params[]='%'.addcslashes($q,'%_\\').'%';$params[]='%'.addcslashes($q,'%_\\').'%';}
$total=(int)DB::val("SELECT COUNT(*) FROM courses c WHERE $where",$params);$pages=max(1,(int)ceil($total/12));$page=max(1,min($pages,(int)($_GET['page']??1)));$offset=($page-1)*12;
$visible=A::visibleSubjectIds();$linkScope=$visible===null?'':($visible?' AND cs.subject_id IN ('.implode(',',array_map('intval',$visible)).')':' AND 1=0');
$courses=DB::all("SELECT c.*,(SELECT COUNT(*) FROM course_subjects cs WHERE cs.course_id=c.id AND cs.is_active=1$linkScope) AS subject_count FROM courses c WHERE $where ORDER BY c.name,c.id LIMIT 12 OFFSET $offset",$params);
$detail=null;$requested=V::optInt($_GET['edit']??$_GET['id']??null,'Course');
if($requested){$p=$params;$p[]=$requested;$detail=DB::one("SELECT c.* FROM courses c WHERE $where AND c.id=?",$p);if(!$detail)not_found();}
if(isset($_GET['edit'])&&!$super)forbidden();$showForm=$super&&(isset($_GET['edit'])||isset($_GET['new'])||request_action()==='save_course'&&$error);$row=$form?:($detail??[]);if($super&&!empty($form['id'])){$old=DB::one('SELECT cover_asset_id FROM courses WHERE id=?',[(int)$form['id']]);$row['cover_asset_id']=$old['cover_asset_id']??null;}
page_header('Global courses'); ?>
<div class="catalogue-toolbar"><p class="muted"><?= e(tr('One shared curriculum, separate centre and batch assignments.')) ?></p><?php if($super): ?><a class="btn btn-primary" href="courses.php?new=1"><?= icon('plus') ?><?= e(tr('Add course')) ?></a><?php endif; ?><a class="btn" href="course_assignments.php"><?= e(tr(A::isTeacher()?'My teaching assignments':'Course assignments')) ?></a></div>
<?php if($error): ?><div class="flash flash-error" role="alert"><?= e(tr($error)) ?></div><?php endif; ?>
<?php if($showForm): ?><section class="card"><h2><?= e(tr(!empty($row['id'])?'Edit course':'Add course')) ?></h2><form method="post" enctype="multipart/form-data" class="form-grid" data-catalogue-form><?= csrf_field() ?><input type="hidden" name="action" value="save_course"><input type="hidden" name="id" value="<?= e((string)($row['id']??'')) ?>"><label><?= e(tr('Code')) ?><input name="code" maxlength="40" pattern="[A-Za-z0-9_-]+" value="<?= e($row['code']??'') ?>" required></label><label><?= e(tr('Name')) ?><input name="name" maxlength="160" value="<?= e($row['name']??'') ?>" required></label><label class="wide"><?= e(tr('Description')) ?><textarea name="description" maxlength="5000"><?= e($row['description']??'') ?></textarea></label><label class="check"><input type="checkbox" name="is_active" value="1"<?= checked((bool)($row['is_active']??1)) ?>><?= e(tr('Active')) ?></label><?php require APP_ROOT.'/app/Views/cover_editor.php'; ?><div class="form-actions"><button class="btn btn-primary"><?= e(tr('Save course')) ?></button><a class="btn" href="courses.php"><?= e(tr('Cancel')) ?></a></div></form></section><?php endif; ?>
<?php if($detail&&!$showForm): $links=DB::all('SELECT s.*,cs.is_active AS link_active FROM course_subjects cs JOIN subjects s ON s.id=cs.subject_id WHERE cs.course_id=?'.$linkScope.' ORDER BY s.name',[$detail['id']]); ?>
<section class="card"><div class="assignment-columns"><div><?= Images::thumbnail($detail['cover_asset_id']??null,$detail['name']) ?></div><div><span class="pill <?= $detail['is_active']?'ok':'' ?>"><?= e(tr($detail['is_active']?'Active':'inactive')) ?></span><h2><?= e($detail['name']) ?></h2><p><?= nl2br(e($detail['description']??'')) ?></p><?php if($super): ?><a class="btn" href="courses.php?edit=<?= (int)$detail['id'] ?>"><?= e(tr('Edit course')) ?></a><?php endif; ?></div></div></section>
<section class="card"><h2><?= e(tr('Course subjects')) ?></h2><div class="assignment-columns"><?php foreach($links as $s): ?><article class="assignment-choice"><?= Images::thumbnail($s['cover_asset_id']??null,'',true) ?><span><strong><?= e($s['name']) ?></strong><br><?= e(tr($s['link_active']?'Active':'inactive')) ?></span><?php if($super): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="link_subject"><input type="hidden" name="course_id" value="<?= (int)$detail['id'] ?>"><input type="hidden" name="subject_id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="active" value="<?= $s['link_active']?0:1 ?>"><?php if($s['link_active']): ?><label class="check"><input type="checkbox" name="confirm_removal" value="1" required><?= e(tr('Confirm deactivation')) ?></label><?php endif; ?><button class="btn"><?= e(tr($s['link_active']?'Deactivate':'Activate')) ?></button></form><?php endif; ?></article><?php endforeach; ?></div><?php if(!$links): ?><p class="muted"><?= e(tr('No subjects linked yet.')) ?></p><?php endif; ?>
<?php if($super): ?><form method="post" class="form-grid spaced"><?= csrf_field() ?><input type="hidden" name="action" value="link_subject"><input type="hidden" name="course_id" value="<?= (int)$detail['id'] ?>"><input type="hidden" name="active" value="1"><label><?= e(tr('Existing global subject')) ?><select name="subject_id" required><?php foreach(DB::all('SELECT id,name FROM subjects WHERE is_active=1 ORDER BY name') as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="btn btn-primary"><?= e(tr('Link subject')) ?></button><a class="btn" href="subjects.php?new=1"><?= e(tr('Add subject')) ?></a></div></form><?php endif; ?></section><?php endif; ?>
<form class="filter-bar" method="get"><label><?= e(tr('Search')) ?><input name="q" value="<?= e($q) ?>" maxlength="100"></label><button class="btn"><?= e(tr('Search')) ?></button></form><div class="catalogue-grid"><?php foreach($courses as $c): ?><article class="card catalogue-card"><?= Images::thumbnail($c['cover_asset_id']??null,$c['name']) ?><div class="catalogue-body"><span class="pill <?= $c['is_active']?'ok':'' ?>"><?= e(tr($c['is_active']?'Active':'inactive')) ?></span><h2><?= e($c['name']) ?></h2><p class="muted"><?= e($c['code']) ?> · <?= (int)$c['subject_count'] ?> <?= e(tr('Subjects')) ?></p><div class="catalogue-links"><a class="btn" href="courses.php?id=<?= (int)$c['id'] ?>"><?= e(tr('View course')) ?></a><?php if($super): ?><a class="btn" href="courses.php?edit=<?= (int)$c['id'] ?>"><?= e(tr('Edit')) ?></a><?php endif; ?></div></div></article><?php endforeach; ?></div><?php if(!$courses): ?><section class="card empty-state"><?= e(tr('No courses available yet.')) ?></section><?php endif; ?>
<div class="pagination"><span><?= $total ?> <?= e(tr('records')) ?></span><nav><?php foreach(['Previous'=>$page-1,'Next'=>$page+1] as $label=>$n): if($n<1||$n>$pages)continue; ?><a class="btn" href="?<?= e(http_build_query(['q'=>$q,'page'=>$n])) ?>"><?= e(tr($label)) ?></a><?php endforeach; ?></nav></div><?php page_footer();
